import React, { useState, useEffect } from 'react';
import { getAllRestaurants } from '../../services/api';
import { useNavigate } from 'react-router-dom';

// --- Small reusable components ---
const Loading = () => (
  <div style={styles.loadingContainer}>
    <div style={styles.spinner}></div>
    <p style={styles.loadingText}>Finding amazing restaurants...</p>
  </div>
);

const EmptyState = ({ searchTerm }) => (
  <div style={styles.emptyState}>
    <span style={styles.emptyIcon}>🍽️</span>
    <h2 style={styles.emptyTitle}>No restaurants found</h2>
    <p style={styles.emptyText}>
      {searchTerm ? 'Try a different search term' : 'Check back soon for new restaurants!'}
    </p>
  </div>
);

const SearchBar = ({ searchTerm, setSearchTerm }) => (
  <div style={styles.searchContainer}>
    <span style={styles.searchIcon}>🔍</span>
    <input
      type="text"
      placeholder="Search by restaurant name, cuisine, or location..."
      value={searchTerm}
      onChange={(e) => setSearchTerm(e.target.value)}
      style={styles.searchInput}
    />
    {searchTerm && (
      <button onClick={() => setSearchTerm('')} style={styles.clearBtn}>
        ✕
      </button>
    )}
  </div>
);

const StatsBar = ({ restaurantsCount, refreshFn }) => (
  <div style={styles.statsBar}>
    <div style={styles.stat}>
      <span style={styles.statNumber}>{restaurantsCount}</span>
      <span style={styles.statLabel}>Restaurants</span>
    </div>
    <div style={styles.statDivider}></div>
    <div style={styles.stat}>
      <span style={styles.statNumber}>⭐ 4.8</span>
      <span style={styles.statLabel}>Avg Rating</span>
    </div>
    <div style={styles.statDivider}></div>
    <div style={styles.stat}>
      <button onClick={refreshFn} style={styles.refreshIconBtn}>🔄</button>
      <span style={styles.statLabel}>Refresh</span>
    </div>
  </div>
);

const RestaurantCard = ({ restaurant, navigate }) => (
  <div
    key={restaurant.id}
    style={styles.card}
    onClick={() => navigate(`/restaurant/${restaurant.id}`)}
    onMouseEnter={(e) => e.currentTarget.style.transform = 'translateY(-8px)'}
    onMouseLeave={(e) => e.currentTarget.style.transform = 'translateY(0)'}
  >
    <div style={styles.imageContainer}>
      <img
        src={restaurant.image_url || 'https://via.placeholder.com/400x250?text=Delicious+Food'}
        alt={restaurant.name}
        style={styles.image}
      />
      <div style={styles.imageBadge}>⭐ 4.8</div>
    </div>
    <div style={styles.cardContent}>
      <h3 style={styles.restaurantName}>{restaurant.name}</h3>
      <p style={styles.cuisine}>✨ {restaurant.cuisine_type}</p>
      <div style={styles.infoRow}>
        <span style={styles.infoItem}>📍 {restaurant.address.split(',')[0]}</span>
      </div>
      <div style={styles.infoRow}>
        <span style={styles.infoItem}>🕒 {restaurant.opening_time} - {restaurant.closing_time}</span>
      </div>
      <button style={styles.viewBtn}>View Details & Reserve →</button>
    </div>
  </div>
);

// --- Main component ---
const RestaurantList = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  const loadRestaurants = async () => {
    try {
      const response = await getAllRestaurants();
      setRestaurants(response.data);
    } catch (error) {
      console.error('Error loading restaurants:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRestaurants();
    const interval = setInterval(loadRestaurants, 10000);
    return () => clearInterval(interval);
  }, []);

  const filteredRestaurants = restaurants.filter(
    r =>
      r.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.cuisine_type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <Loading />;

  return (
    <div style={styles.container}>
      <div style={styles.hero}>
        <h1 style={styles.heroTitle}>Discover & Reserve</h1>
        <p style={styles.heroSubtitle}>Find your perfect dining experience</p>
        <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} />
        <StatsBar restaurantsCount={restaurants.length} refreshFn={loadRestaurants} />
      </div>

      {filteredRestaurants.length === 0 ? (
        <EmptyState searchTerm={searchTerm} />
      ) : (
        <div style={styles.grid}>
          {filteredRestaurants.map(r => (
            <RestaurantCard key={r.id} restaurant={r} navigate={navigate} />
          ))}
        </div>
      )}
    </div>
  );
};

